contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // amount to burn and an address to observe balances (we will use address(this) as caller)
    function run(uint256 burnAmount, address addr) public payable {
        require(true);
        // read before values
        uint256 beforeTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 beforeBalanceCaller = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeBalanceAddr = c.balanceOf(addr); if (__ESBMC_reverted()) return;

        // attempt burn and record whether it reverted
        bool reverted;
        c.burn(burnAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 afterBalanceCaller = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterBalanceAddr = c.balanceOf(addr); if (__ESBMC_reverted()) return;

        // If burn succeeded then caller must have been owner and balances/totalSupply reduced by burnAmount from caller
        // We cannot directly read owner if not allowed, but owner() is public so we can compare.
        address owner = c.owner(); if (__ESBMC_reverted()) return;
        // assert: if not reverted then caller is owner and totalSupply decreased by burnAmount and caller balance decreased by burnAmount, other balances unchanged
        assert(reverted || (
            owner == address(this)
            && afterTotal + burnAmount == beforeTotal
            && afterBalanceCaller + burnAmount == beforeBalanceCaller
            && afterBalanceAddr == beforeBalanceAddr
        ));
    }
    receive() external payable {}
}

