import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 burnAmount, address addr) internal {
        vm.assume(true);
        uint256 beforeTotal;
        try c.totalSupply() returns (uint256 __r) { beforeTotal = __r; } catch { return; }
        uint256 beforeBalanceCaller;
        try c.balanceOf(address(this)) returns (uint256 __r) { beforeBalanceCaller = __r; } catch { return; }
        uint256 beforeBalanceAddr;
        try c.balanceOf(addr) returns (uint256 __r) { beforeBalanceAddr = __r; } catch { return; }
        bool reverted;
        try c.burn(burnAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterTotal;
        try c.totalSupply() returns (uint256 __r) { afterTotal = __r; } catch { return; }
        uint256 afterBalanceCaller;
        try c.balanceOf(address(this)) returns (uint256 __r) { afterBalanceCaller = __r; } catch { return; }
        uint256 afterBalanceAddr;
        try c.balanceOf(addr) returns (uint256 __r) { afterBalanceAddr = __r; } catch { return; }
        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        assertTrue(reverted || (
            owner == address(this)
            && afterTotal + burnAmount == beforeTotal
            && afterBalanceCaller + burnAmount == beforeBalanceCaller
            && afterBalanceAddr == beforeBalanceAddr
        ));
    }

    function testFuzz_run(uint256 burnAmount, address addr) public {
        vm.assume(addr.code.length == 0 && uint160(addr) > 0xffff && addr != address(this) && addr != address(c) && addr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && addr != 0x000000000000000000636F6e736F6c652e6c6f67 && addr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && addr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(burnAmount, addr);
    }

    receive() external payable {}
}
